package com.tenora365.controller;import com.tenora365.entity.*;import com.tenora365.repository.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/super") @PreAuthorize("hasRole('SUPER_ADMIN')") public class SuperAdminController{final SchoolRepository schools;final UserRepository users;final PasswordEncoder enc;SuperAdminController(SchoolRepository s,UserRepository u,PasswordEncoder e){schools=s;users=u;enc=e;}@GetMapping("/schools")List<School> schools(){return schools.findAll();}@PostMapping("/schools")Map<String,Object> create(@RequestBody Map<String,String> x){School s=new School();s.setName(x.get("name"));s.setCode(x.get("code"));s.setEmail(x.get("email"));s=schools.save(s);User u=new User();u.setSchool(s);u.setUsername(x.getOrDefault("adminUsername",x.get("code").toLowerCase()+"@admin"));u.setFullName(x.getOrDefault("adminName","School Admin"));u.setRole("SCHOOL_ADMIN");u.setPasswordHash(enc.encode(x.getOrDefault("adminPassword","ChangeMe@123")));users.save(u);return Map.of("school",s,"adminUsername",u.getUsername());}}
